protocol InitechPayment {
  roles User, Clerk, Reader, Docs, Approver1, Approver2, Bank;

  User -> Clerk : Task(str) where len <= 2000;
  Clerk -> Reader : Fetch(enum{acme, globex, initech, umbrella, hooli, soylent, vandelay, wonka});
  Reader -> Docs : Get(enum{acme, globex, initech, umbrella, hooli, soylent, vandelay, wonka});
  Docs -> Reader : Invoice(str);

  choice at Reader {
    Reader -> Approver1 : Extracted({payee: enum{acme, globex, initech, umbrella, hooli, soylent, vandelay, wonka}, amount: int}) where (amount >= 1 and amount <= 50000);
    Reader -> Clerk : Status(enum{found, not_found, unreadable});
  } or {
    Reader -> Clerk : Status(enum{found, not_found, unreadable});
  }

  choice at Clerk {
    Clerk -> Approver1 : Request(str) where len <= 1000;
    choice at Approver1 {
      Approver1 -> Clerk : Ok({payee: enum{acme, globex, initech, umbrella, hooli, soylent, vandelay, wonka}, amount: int});
      Clerk -> Approver2 : Request({payee: enum{acme, globex, initech, umbrella, hooli, soylent, vandelay, wonka}, amount: int}) where (amount >= 1 and amount <= 50000);
      choice at Approver2 {
        Approver2 -> Clerk : Ok({payee: enum{acme, globex, initech, umbrella, hooli, soylent, vandelay, wonka}, amount: int});
        Clerk -> Bank : Transfer({payee: enum{acme, globex, initech, umbrella, hooli, soylent, vandelay, wonka}, amount: int}) where (amount >= 1 and amount <= 50000);
        Bank -> Clerk : Receipt(str) where len <= 500;
        Clerk -> User : Report(str) where len <= 4000;
      } or {
        Approver2 -> Clerk : Rejected(unit);
        Clerk -> User : Report(str) where len <= 4000;
      }
    } or {
      Approver1 -> Clerk : Rejected(unit);
      Clerk -> User : Report(str) where len <= 4000;
    }
  } or {
    Clerk -> User : Report(str) where len <= 4000;
  }

  end;
}

